    eligAskText: "Présentez votre cas au bureau des douanes algériennes avec une question précise : « Je veux garder ce véhicule en Algérie, sous quel régime puis-je le déclarer ? » Gardez la réponse, sa date et le service contacté.",
    eligGuide: "Par où commencer : le guide complet",
    achatIntro: "Une voiture proche de son troisième anniversaire laisse peu de place à un retard de vente, de transport ou de dossier. Simulez la date de déclaration prévue, puis une date décalée de quelques semaines.",
    achatAskTitle: "À régler avec le vendeur avant de payer",
