    achatAsk5: "Qui assure la voiture, qui la conduit jusqu'au port et qui garde les originaux.",
    achatBudgetTitle: "Le coût complet",
    achatBudgetHint: "Achat, acheminement, traversée, frais, droits et taxes : tant que la douane n'a pas confirmé les droits et taxes, gardez un montant « à chiffrer ».",
    achatGuide: "Construire le budget poste par poste",
    exportIntro: "Pour quitter l'Union européenne, la voiture doit être déclarée à l'exportation. Cette déclaration donne deux choses : le DAE, qui accompagne la voiture, et le MRN, son numéro officiel.",
    exportWhoTitle: "Qui fait la déclaration ?",
    exportWhoSeller: "Le vendeur",
    exportWhoMe: "Moi-même",
    exportWhoAgent: "Un transitaire",
    exportWhoSellerText: "Le plus simple : demandez-le avant de signer. Le vendeur dépose la déclaration et vous remet le DAE avec son MRN.",
    exportWhoMeText: "Vous déposez la déclaration par voie électronique, au bureau de douane du lieu où le vendeur est établi, avec la facture et une copie de la carte grise.",
    exportWhoAgentText: "Un commissionnaire en douane (transitaire) dépose la déclaration pour vous. Demandez-lui son prix et son délai avant le départ.",
    exportHowTitle: "Comment ça se passe",
    exportHow1: "Où : au bureau de douane où l'exportateur est établi. Pour une voiture achetée en France, celui du lieu où le vendeur est établi.",
    exportHow2: "Avec quoi : la facture d'achat et une copie de la carte grise.",
    exportHow3: "Le MRN : dès que la douane accepte la déclaration, son système attribue ce numéro, reconnu dans toute l'Union européenne. Il sert à suivre la sortie de la voiture.",
    exportHow4: "Le DAE (document d'accompagnement export) accompagne la voiture jusqu'au port de sortie.",
    exportHow5: "Une fois la sortie constatée, la déclaration passe à l'état « exporté » : c'est votre preuve de sortie. Gardez-la.",
    exportMrnTitle: "Votre MRN",
    exportMrnLabel: "Numéro MRN (sur le DAE)",
    exportMrnHint: "Noté sur cet appareil pour l'avoir sous la main au port. BledWay ne le vérifie pas.",
    exportOtherCountry: "Voiture achetée hors de France : la déclaration se fait dans le pays d'achat. Demandez la marche à suivre à la douane de ce pays.",
