    travValence: "Avec Baleària : Valence–Alger. À partir du 1er janvier 2027, Baleària n'embarque plus de véhicules à exporter sur Valence–Mostaganem. Présentez-vous au port au moins 4 h avant le départ. Envoyez le DAE et votre réservation à export.algerie@balearia.com au moins 6 h avant.",
    travBarcelone: "Avec Baleària : Barcelone–Alger. Présentez-vous au port au moins 6 h avant le départ. Envoyez le DAE et votre réservation à exportacion.barcelona@balearia.com au moins 6 h avant.",
    travAlmeria: "Avec Baleària : Almería–Oran et Almería–Ghazaouet. Demandez à Baleària l'adresse d'envoi du DAE et l'heure de présentation au port pour ce départ.",
